-- TripOps: THÊM 50 dịch vụ demo khu vực Đà Lạt (22 Hotel / 22 Fnb / 3 Transportation / 3 Attraction).
-- Nguồn tên/địa chỉ: xem dalat-50-services.sources.md. Giá/sức chứa/ảnh là dữ liệu test.
-- Không UPDATE/DELETE dịch vụ đang có. Chạy lại bỏ qua theo Provider + tên + danh mục.
-- Chạy migration trước. SSMS: chọn đúng database rồi Execute toàn bộ file.
SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @ProviderEmail nvarchar(191) = N'provider@tripops.test';
-- NULL: lấy dịch vụ đầu tiên của Provider có thumbnail và gallery JSON; có thể chỉ định ID.
DECLARE @TemplateServiceId int = NULL;
DECLARE @ProviderId nvarchar(36), @Thumbnail nvarchar(max), @Images nvarchar(max);
DECLARE @Now datetime2(7) = SYSUTCDATETIME();
DECLARE @Seed TABLE (
    ordinal int PRIMARY KEY, category nvarchar(50), sub_category nvarchar(100),
    name nvarchar(255), description nvarchar(max), street nvarchar(255), full_address nvarchar(500),
    ward nvarchar(100), price_from decimal(12,2), price_to decimal(12,2), capacity int,
    operating_hours nvarchar(100), policies nvarchar(max)
);
INSERT INTO @Seed VALUES
(1, N'Hotel', N'Khách sạn', N'Dalat Palace Heritage', N'Khách sạn mang kiến trúc Pháp, nằm gần hồ Xuân Hương và khu trung tâm Đà Lạt. [Dữ liệu demo] Giá, sức chứa và ảnh minh họa dùng để kiểm thử; không phải báo giá hoặc cam kết cung cấp của cơ sở.', N'02 Trần Phú', N'02 Trần Phú, Đà Lạt, Lâm Đồng', NULL, 700000, 1400000, 20, NULL, N'["[Dữ liệu demo] Giá, sức chứa và ảnh minh họa dùng để kiểm thử; không phải báo giá hoặc cam kết cung cấp của cơ sở.", "Đơn vị tính giá mẫu: VNĐ/phòng/đêm. Sức chứa lưu trú là số phòng mẫu; các loại còn lại là số chỗ/khách mẫu.", "Tên, địa chỉ và giờ hoạt động tham khảo nguồn web; cần liên hệ cơ sở để xác nhận trước khi sử dụng thực tế.", "Nguồn tham khảo: https://www.dalatpalacehotel.com/gioithieu/"]'),
(2, N'Hotel', N'Khách sạn', N'Dalat Du Parc', N'Cơ sở lưu trú trong tòa nhà có lịch sử từ năm 1932, thuận tiện khám phá trung tâm Đà Lạt. [Dữ liệu demo] Giá, sức chứa và ảnh minh họa dùng để kiểm thử; không phải báo giá hoặc cam kết cung cấp của cơ sở.', N'07 Trần Phú', N'07 Trần Phú, Đà Lạt, Lâm Đồng', NULL, 900000, 1750000, 30, NULL, N'["[Dữ liệu demo] Giá, sức chứa và ảnh minh họa dùng để kiểm thử; không phải báo giá hoặc cam kết cung cấp của cơ sở.", "Đơn vị tính giá mẫu: VNĐ/phòng/đêm. Sức chứa lưu trú là số phòng mẫu; các loại còn lại là số chỗ/khách mẫu.", "Tên, địa chỉ và giờ hoạt động tham khảo nguồn web; cần liên hệ cơ sở để xác nhận trước khi sử dụng thực tế.", "Nguồn tham khảo: https://dalat.vn/en/dalatduparc"]'),
