DECLARE @Inserted TABLE (id int, category nvarchar(50), name nvarchar(255));
BEGIN TRY
    BEGIN TRANSACTION;
    SELECT @ProviderId = u.id FROM dbo.users u
    JOIN dbo.business_profiles bp ON bp.user_id = u.id
    WHERE u.email = @ProviderEmail AND u.role = N'Provider'
      AND u.status = N'Active' AND bp.status = N'Approved';
    IF @ProviderId IS NULL
        THROW 51001, N'Cần có Provider hoạt động, hồ sơ đã duyệt. Kiểm tra @ProviderEmail.', 1;

    -- Đọc nguồn ảnh từ bảng thật; không tải lại và không tạo ảnh mới trên Cloudinary.
    SELECT TOP (1) @TemplateServiceId = s.id, @Thumbnail = s.thumbnail_url, @Images = s.images
    FROM dbo.services s
    WHERE s.provider_id = @ProviderId
      AND (@TemplateServiceId IS NULL OR s.id = @TemplateServiceId)
      AND NULLIF(s.thumbnail_url, N'') IS NOT NULL AND ISJSON(s.images) = 1
    ORDER BY s.id;
    IF @Thumbnail IS NULL OR @Images IS NULL
        THROW 51002, N'Cần ít nhất một dịch vụ có thumbnail và gallery JSON để clone ảnh.', 1;

    INSERT INTO [dbo].[services] (
        provider_id, category, sub_category, name, description, price, price_from, price_to,
        capacity, star_rating, amenities, policies, province, ward, street, full_address,
        latitude, longitude, thumbnail_url, images, rating, status, is_paused,
        rejection_reason, hidden_reason, operating_hours, created_at, updated_at
    )
    OUTPUT inserted.id, inserted.category, inserted.name INTO @Inserted
    SELECT @ProviderId, s.category, s.sub_category, s.name, s.description, s.price_from, s.price_from, s.price_to,
        s.capacity, NULL, N'[]', s.policies, N'Lâm Đồng', s.ward, s.street, s.full_address,
        NULL, NULL, @Thumbnail, @Images, NULL, N'Approved', 0,
        NULL, NULL, s.operating_hours, @Now, @Now
    FROM @Seed s
    WHERE NOT EXISTS (
        SELECT 1 FROM [dbo].[services] existing WITH (UPDLOCK, HOLDLOCK)
        WHERE existing.provider_id = @ProviderId AND existing.category = s.category AND existing.name = s.name
    );
    COMMIT TRANSACTION;
    SELECT COUNT(*) AS inserted_count, 50-COUNT(*) AS skipped_existing_count,
        @TemplateServiceId AS cloned_images_from_service_id FROM @Inserted;
    SELECT category, COUNT(*) AS inserted_count FROM @Inserted GROUP BY category ORDER BY category;
    SELECT id, category, name FROM @Inserted ORDER BY id;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
